"""k4_gemm — generated by torch-helion (do not edit).

GEMM kernel: grid [T=512, N=256], reduction K=512
  acc_mm_6 = lhs @ w0  (permute_11)
  add_5 = add(in0, acc_mm_6) 
  store add_5 <- add_5
Planned tiles: {'tile_t': 32, 'tile_n': 64, 'tile_k': 128}  (analytic estimate 20,155 cycles)

Run through Loom from the repository root:

    uv run python results/llama_block/kernels/k4_gemm.py --config results/llama_block/kernels/config_files/k4_gemm.json --njobs 8 --debug --topk-candidates 1
"""

from __future__ import annotations

import sys

import torch
import helion
import helion.language as hl

from loom import LoomKernel
from loom.loom_utils.kernel_size import resolve_kernel_shape_args
from helion_mlir.custom_op import broadcast  # noqa: F401  (registers the op)


def _k4_gemm(lhs: torch.Tensor, w0: torch.Tensor, in0: torch.Tensor) -> tuple[torch.Tensor, ...]:
    t, k = lhs.size()
    _, n = w0.size()
    out_add_5 = torch.empty([t, n], dtype=torch.float16, device=lhs.device)
    for tile_t, tile_n in hl.tile([t, n]):
        acc_mm_6 = hl.zeros([tile_t, tile_n], dtype=torch.float16)
        for tile_k in hl.tile(k):
            xt = lhs[tile_t, tile_k]
            acc_mm_6 = hl.dot(xt, w0[tile_k, tile_n], acc=acc_mm_6)
        ld_2 = in0[tile_t, tile_n]
        add_5_1 = ld_2 + acc_mm_6
        out_add_5[tile_t, tile_n] = add_5_1
    return out_add_5,


class K4Gemm(LoomKernel):
    """Loom entry point for kernel ``k4_gemm``."""

    kernel_name = "k4_gemm"
    assume_divisible: bool = True

    ARG_SHAPES = [('lhs', [512, 512]), ('w0', [512, 256]), ('in0', [512, 256])]
    CONSTEXPRS = []
    TILES = {'tile_t': 32, 'tile_n': 64, 'tile_k': 128}

    kernel = helion.kernel(
        static_shapes=False,
        autotune_config_overrides={
            "range_unroll_factors": [0, 0],
            "range_num_stages": [0, 0],
        },
    )(_k4_gemm)

    def __init__(self, shape: dict[str, int] | None = None) -> None:
        if shape:
            raise SystemExit("generated kernels have fixed shapes; regenerate with torch-helion instead")

    @classmethod
    def bind_args(cls) -> tuple:
        args = [torch.empty(shape, dtype=torch.float16) for _, shape in cls.ARG_SHAPES]
        return tuple(args + [v for _, v in cls.CONSTEXPRS])


if __name__ == "__main__":
    try:
        shape, normalized_argv = resolve_kernel_shape_args(sys.argv)
    except ValueError as exc:
        raise SystemExit(str(exc)) from exc

    sys.argv = normalized_argv
    K4Gemm(shape).run()
